CREATE TABLE IF NOT EXISTS portfolio_knowledge (
  id TEXT PRIMARY KEY,
  category TEXT NOT NULL,
  title TEXT NOT NULL,
  content TEXT NOT NULL CHECK (length(content) <= 2000),
  url TEXT,
  link_label TEXT,
  keywords TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_portfolio_knowledge_active
  ON portfolio_knowledge (is_active, sort_order);

INSERT INTO portfolio_knowledge
  (id, category, title, content, url, link_label, keywords, sort_order)
VALUES
  ('overview', 'overview', 'Sujeet Khadka',
    'Sujeet Khadka is a product and UI/UX designer based in Lalitpur, Nepal (UTC +05:45). He designs mobile products through research, interaction design, prototyping, developer handoff, and implementation review. His portfolio covers a shipped maternity-care app, mobile games, and independent interaction-design studies.',
    '/', 'Explore the portfolio', 'background bio introduction product designer ui ux mobile lalitpur nepal', 10),
  ('skills-product-design', 'skills', 'Product design capabilities',
    'Sujeet works across user research, user flows, UX audits, product thinking, interaction design, design systems, wireframing, high-fidelity prototyping, usability testing, responsive UI, developer handoff, and implementation review. His primary design tool is Figma.',
    '/#skills', 'See how Sujeet works', 'skills research strategy figma ui ux wireframe prototype testing responsive handoff', 20),
  ('skills-visual-frontend', 'skills', 'Visual design and front-end basics',
    'His visual-design work includes branding, identity, typography, composition, and Photoshop. He uses semantic HTML, CSS, JavaScript, Git, VS Code, and front-end fundamentals to bridge design and implementation. The portfolio toolkit also includes GitHub and Godot.',
    '/#skills', 'View skills', 'technology technologies tools visual branding photoshop html css javascript git github vscode godot frontend', 21),
  ('project-aama-cure', 'projects', 'Aama Cure',
    'Aama Cure is a shipped maternity-care product for Android and iOS, designed for Nepali mothers. It brings together fertility and pregnancy tracking, vaccinations, counselling, and postpartum care. Sujeet contributed research, user flows, wireframes, prototypes, usability testing, developer handoff, and implementation review as the UI/UX designer at Neptune TechZone.',
    'https://aamacure.com', 'Visit Aama Cure', 'project mobile health maternity pregnancy android ios shipped neptune', 30),
  ('project-carrom-karrom', 'projects', 'Carrom Karrom',
    'Carrom Karrom is a shipped lightweight mobile carrom game redesigned for older, low-storage phones. It has more than 50,000 Google Play downloads. Sujeet designed the complete interface and visual assets in Figma; Sagar Devkota handled game logic and deployment.',
    '/blog/carrom-karrom/', 'Read the Carrom Karrom design story', 'project game mobile google play 50k low storage figma carrom', 31),
  ('project-esewa', 'projects', 'eSewa: clearer money actions',
    'This self-initiated redesign proposal explored how to reduce accidental top-ups and home-screen clutter in eSewa. It was based on real user complaints and a heuristic evaluation, and covered research, analysis, and redesign.',
    'https://medium.com/design-bootcamp/improving-esewas-user-experience-reducing-accidental-top-ups-fixing-home-screen-clutter-6a7c7afc0c70', 'Read the eSewa case study', 'project esewa redesign fintech heuristic research case study', 32),
  ('project-nakka', 'projects', 'Nakka: Nepali Traditional Game',
    'Nakka brings a traditional Nepali game to mobile with offline play. The portfolio includes a design story about the project.',
    '/blog/nakka/', 'Read the Nakka design story', 'project nakka nepali game mobile offline', 33),
  ('project-2048', 'projects', '2048 Dark Mode Edition',
    '2048 Dark Mode Edition is a UX-focused redesign that adds dark mode, move history, and sound feedback.',
    '/blog/2048-dark-mode/', 'Explore the 2048 redesign', 'project 2048 game dark mode ux move history sound', 34),
  ('project-bus', 'projects', 'Online Bus Reservation System',
    'The Online Bus Reservation System was Sujeet’s final-year project. He handled UI/UX design and the front-end build using Figma, HTML, CSS, Flowbite, Node.js, and SQLite.',
    '/blog/bus-reservation-system/', 'Explore the bus reservation project', 'project bus reservation final year figma html css flowbite node sqlite', 35),
  ('project-experiments', 'projects', 'Other projects and experiments',
    'Other portfolio projects include Nepali Festive Counter, The Progress Bar np, and Connectum, a connect-the-dots game whose UI and assets were designed in Figma.',
    '/blog/', 'Browse the project notebook', 'projects festive counter progress bar connectum game experiment', 36),
  ('experience-okay-journey', 'experience', 'Graphic Design Intern — Okay Journey',
    'From September to December 2023, Sujeet was a Graphic Design Intern at Okay Journey Pvt. Ltd. He created more than 10 promotional graphics and email templates for digital campaigns and worked with content teams on responsive visual communication.',
    '/#experience', 'View professional experience', 'career experience intern graphic design okay journey 2023 campaigns', 40),
  ('experience-kmag', 'experience', 'Graphic Designer & UI/UX — KMAG',
    'From August to October 2024, Sujeet worked part-time as a Graphic Designer and UI/UX designer at KMAG Pvt. Ltd. He collaborated on a Figma UI redesign across mobile and desktop and created product assets and logo drafts.',
    '/#experience', 'View professional experience', 'career experience kmag 2024 part time figma redesign mobile desktop', 41),
  ('experience-neptune', 'experience', 'UI/UX Designer — Neptune TechZone',
    'From January 2026 to the present, Sujeet has worked as a UI/UX Designer at Neptune TechZone on Aama Cure. He designed and shipped the Android and iOS maternity-health app end to end through research, wireframes, prototypes, testing, handoff, and implementation review.',
    '/#experience', 'View professional experience', 'career experience neptune techzone aama cure 2026 present ui ux', 42),
  ('experience-upwork', 'experience', 'Freelance UI/UX & Graphic Designer',
    'From August 2026 to the present, Sujeet has worked through Upwork as a freelance UI/UX and Graphic Designer for webapex.com.au, an Australian client. He delivers structured web banners and digital assets with responsive layouts and international brand standards.',
    '/#experience', 'View professional experience', 'career experience upwork freelance webapex australia 2026 present', 43),
  ('writing', 'writing', 'Design writing and project notes',
    'Sujeet writes about interaction design, product decisions, visual design, and the details that shape digital experiences. His project notebook documents the decisions, constraints, and lessons behind his games and web experiments; more articles are available on Medium.',
    '/blog/', 'Browse the project notebook', 'writing articles medium blog notebook interaction design visual design', 50),
  ('contact', 'contact', 'Contact Sujeet',
    'For a project, product challenge, or role, email Sujeet at email@sujeetkhadka.com.np. His portfolio also links to Figma, GitHub, LinkedIn, Medium, Behance, Dribbble, and YouTube profiles. The current availability message is shown on the portfolio homepage.',
    '/#contact', 'Contact Sujeet', 'contact email hire availability linkedin github figma medium behance dribbble youtube', 60)
ON CONFLICT(id) DO UPDATE SET
  category = excluded.category,
  title = excluded.title,
  content = excluded.content,
  url = excluded.url,
  link_label = excluded.link_label,
  keywords = excluded.keywords,
  sort_order = excluded.sort_order,
  is_active = 1,
  updated_at = CURRENT_TIMESTAMP;
